style.css:
@-moz-document domain("google.com") {
/* Variables for the custom girly purple palette */
  :root {
    --mario-bg: #f3eafd;          /* Soft pastel lavender background */
    --mario-card: #ffffff;        /* Crisp white for search bar/cards */
    --mario-purple: #9b6bc3;      /* Vibrant mid-tone purple */
    --mario-dark-purple: #5c3d75; /* Deep rich purple for text */
    --mario-pink: #ffb7b2;        /* Soft blush pink accent */
    --mario-light-pink: #ffe6e5;  /* Very pale pink for hover states */
  }

  /* Main Background */
  body, html {
    background-color: var(--mario-bg) !important;
    font-family: 'Courier New', Courier, monospace, sans-serif !important; /* Retro arcade touch */
  }

  /* Google Logo Styling (Fallback text style or tint helper) */
  img[alt="Google"] {
    /* Gives a subtle playful glow to the classic logo */
    filter: hue-rotate(240deg) saturate(1.2) !important;
  }

  /* Search Bar Styling - Shaped like a Mario brick/pipe hybrid */
  div.a4bIc, form#tsf div.A8SBwf, .RNNXgb {
    background-color: var(--mario-card) !important;
    border: 3px solid var(--mario-purple) !important;
    border-radius: 20px !important;
    box-shadow: 0 4px 0 var(--mario-dark-purple) !important;
  }

  /* Search Bar on Focus */
  input.gLFyf:focus, .a4bIc:focus-within {
    border-color: var(--mario-pink) !important;
  }

  /* Search Button */
  button.Tg7LZd, .lsbb input[type="submit"] {
    background-color: var(--mario-purple) !important;
    border-radius: 0 15px 15px 0 !important;
  }

  /* Search Button Hover Effect */
  button.Tg7LZd:hover {
    background-color: var(--mario-pink) !important;
  }

  /* Text Colors */
  input.gLFyf, div.internal-tab-content {
    color: var(--mario-dark-purple) !important;
  }

  /* Footer and Links */
  div.KxwPGc, a.pHiOh {
    background-color: #e5d4f2 !important;
    color: var(--mario-dark-purple) !important;
    border-top: 2px dashed var(--mario-purple) !important;
  }

  a:hover {
    color: var(--mario-pink) !important;
  }
}
